class Solution {
public:
    bool canSortArray(vector<int>& nums) {
        int n = nums.size();
        int prevMax = 0;
        int i = 0;
        while (i < n) {
            int bits = __builtin_popcount((unsigned)nums[i]);
            int curMin = nums[i];
            int curMax = nums[i];
            while (i < n && __builtin_popcount((unsigned)nums[i]) == bits) {
                if (nums[i] < curMin) curMin = nums[i];
                if (nums[i] > curMax) curMax = nums[i];
                ++i;
            }
            if (curMin < prevMax) return false;
            prevMax = curMax;
        }
        return true;
    }
};
